import org.springframework.data.domain.*;

// 絞り込み済みの申請が45件あるとする(新しい順。本物は DB が返す)
List<String> all = new ArrayList<>();
for (int i = 45; i >= 1; i--) all.add("申請" + i);

// ここを変えてみよう:page を 0〜3、size を 10 や 50 にして再実行
int page = 1;
int size = 20;

Pageable req = PageRequest.of(page, size,
        Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id")));
System.out.println("要求: " + req);
System.out.println("OFFSET(読み飛ばす件数) = " + req.getOffset());

// DB の LIMIT / OFFSET の代わりに subList で切り出す
int from = (int) Math.min(req.getOffset(), all.size());
int to = Math.min(from + size, all.size());
Page<String> result = new PageImpl<>(all.subList(from, to), req, all.size());

System.out.println("中身: " + result.getContent());
System.out.println("総件数 " + result.getTotalElements()
        + " / 総ページ " + result.getTotalPages()
        + " / 今 " + (result.getNumber() + 1) + " ページ目(画面表示は +1)");
System.out.println("前へ? " + result.hasPrevious() + " 次へ? " + result.hasNext());

// ここを変えてみよう:-1 を 0 にすると例外が出なくなる
try {
    PageRequest.of(-1, 20);
} catch (IllegalArgumentException e) {
    System.out.println("PageRequest.of(-1, 20) → " + e.getMessage());
}

import java.util.function.Predicate;

record Req(long id, String title, String status, String type) {}

List<Req> data = List.of(
    new Req(1, "大阪出張の交通費", "SUBMITTED", "EXPENSE"),
    new Req(2, "夏季休暇", "APPROVED", "LEAVE"),
    new Req(3, "出張用モバイルルーター", "SUBMITTED", "PURCHASE"),
    new Req(4, "福岡出張の宿泊費", "RETURNED", "EXPENSE"),
    new Req(5, "モニター購入", "SUBMITTED", "PURCHASE"));

// 検索条件(null = 指定なし)
// ここを変えてみよう:null にしたり、"EXPENSE" や "休暇" にしたりして再実行
String status = "SUBMITTED";
String type = null;
String keyword = "出張";

// Specification と同じ考え方:値がある条件だけ部品を足す
List<Predicate<Req>> conds = new ArrayList<>();
if (status != null) conds.add(r -> r.status().equals(status));
if (type != null) conds.add(r -> r.type().equals(type));
if (keyword != null && !keyword.isBlank())
    conds.add(r -> r.title().contains(keyword));

// allOf と同じ:全部を AND でつなぐ(部品が0個なら全件)
Predicate<Req> where = conds.stream().reduce(r -> true, Predicate::and);

System.out.println("使った条件: " + conds.size() + " 個");
data.stream().filter(where).forEach(System.out::println);

// 派生クエリで同じことをすると、条件の有無の組み合わせだけメソッドが要る
for (int n = 1; n <= 6; n++) {
    System.out.println("任意条件 " + n + " 個 → 派生クエリ " + (1 << n) + " 本");
}

import org.springframework.web.util.UriComponentsBuilder;
import org.springframework.util.MultiValueMap;

// 今の検索条件(null = 指定なし)
// ここを変えてみよう:keyword を "50% & 割引" にする / type に "EXPENSE" を入れる
String status = "SUBMITTED";
String type = null;
String keyword = "出張 大阪";
int page = 0;

// 「次へ」のリンク:条件を全部引き継いで page だけ +1 する。
// encode() で日本語・空白・% などを URL エンコードする
String next = UriComponentsBuilder.fromPath("/requests/search")
        .queryParamIfPresent("status", Optional.ofNullable(status))
        .queryParamIfPresent("type", Optional.ofNullable(type))
        .queryParamIfPresent("keyword", Optional.ofNullable(keyword))
        .queryParam("page", page + 1)
        .encode()
        .build()
        .toUriString();
System.out.println("次へ: " + next);

// ブックマークから戻ってきたとき:URL だけで条件を復元できる
// build(true) は「すでにエンコード済み」という意味
MultiValueMap<String, String> q = UriComponentsBuilder.fromUriString(next)
        .build(true)
        .getQueryParams();
q.forEach((k, v) -> System.out.println("  " + k + " = "
        + URLDecoder.decode(v.get(0), java.nio.charset.StandardCharsets.UTF_8)));

